@stereotype(CIMStereotype.enumeration)
class VsPpccControlKind(Enum):
    '''
    Types applicable to the control of real power and/or DC voltage by voltage
    source converter.
    '''

    pPcc = 'pPcc'
    '''
    Control variable (target) is real power at PCC bus.
    '''
    
    pPccAndUdcDroop = 'pPccAndUdcDroop'
    '''
    Control variables (targets) are both active power at point of common
    coupling and local DC voltage, with the droop.
    '''
    
    pPccAndUdcDroopPilot = 'pPccAndUdcDroopPilot'
    '''
    Control variables (targets) are both active power at point of common
    coupling and the pilot DC voltage, with the droop.
    '''
    
    pPccAndUdcDroopWithCompensation = 'pPccAndUdcDroopWithCompensation'
    '''
    Control variables (targets) are both active power at point of common
    coupling and compensated DC voltage, with the droop; compensation factor
    is the resistance, as an approximation of the DC voltage of a common
    (real or virtual) node in the DC network.
    '''
    
    udc = 'udc'
    '''
    Control variable (target) is DC voltage and real power at PCC bus is
    derived.
    '''
    
    @property
    def __namespace__(self):
        return 'http://iec.ch/TC57/2013/CIM-schema-cim16#'
    @property
    def __package__(self):
        return 'DC'
    @property
    def __minOccurs__(self):
        return '0'
    @property
    def __maxOccurs__(self):
        return 'unbounded'
    
